from pathlib import Path
from html import escape as E
import json,shutil
R=Path(__file__).resolve().parents[1];O=R/'site'
CATS=[('start','认识篮球','先看懂一场球在做什么','得分、场地与球权，从最基本的问题进入。'),('rules','规则不再懵','先会停，再会走','运球、轴心脚、接触与不同球局的约定。'),('skills','基础技术','把球变得可控','运、传、投、上篮，从慢动作开始。'),('team','跑位与配合','没拿球，也能帮到队友','接应、传切与防守，先建立空间感。'),('practice','练习与上场','带一个小目标去球场','第一次约球、独练、双人练习与四周路线。')]
M={x[0]:x for x in CATS}
L=json.loads((R/'content/lessons.json').read_text())
def court(interactive=False):
 return '''<svg viewBox="0 0 640 400" role="img" aria-label="篮球半场：篮筐在上方，持球队友在左侧，你在右侧。虚线表示可能的传球路线。"><rect x="25" y="20" width="590" height="355" fill="none" stroke="currentColor" stroke-width="2"/><path d="M230 20V170H410V20M265 20V56H375V20 M80 20V70C80 345 560 345 560 70V20" fill="none" stroke="currentColor" opacity=".65" stroke-width="2"/><circle cx="320" cy="170" r="60" fill="none" stroke="currentColor" opacity=".65"/><path d="M260 375A60 60 0 0 1 380 375" fill="none" stroke="currentColor"/><path d="M290 40H350" stroke="#f5b45d" stroke-width="4"/><circle cx="320" cy="55" r="10" stroke="#f5b45d" fill="none" stroke-width="3"/><line data-pass-line x1="160" y1="260" x2="450" y2="260" stroke="#f5b45d" stroke-dasharray="7 6" stroke-width="2"/><circle cx="160" cy="260" r="22" fill="#f5b45d"/><text x="160" y="265" text-anchor="middle" fill="#28251f" font-size="13">友</text><circle cx="140" cy="284" r="8" fill="#e67b44"/><g data-opponent transform="translate(305 260)"><circle r="22" fill="#c06b56"/><text text-anchor="middle" y="5" fill="white" font-size="13">对</text></g><g data-you transform="translate(450 260)"><circle r="23" fill="#fff7e7" stroke="#f5b45d" stroke-width="3"/><text text-anchor="middle" y="5" fill="#28251f" font-size="13">你</text></g><text x="50" y="350" fill="currentColor" font-size="11" opacity=".7">半场教学示意 · 不按比赛尺寸比例</text></svg>'''
def widget():
 return '<div class="diagram-box" data-basket-court><div class="eyebrow">COURT LAB / 接应实验室</div><h2>站在空处，就一定能接到球吗？</h2>'+court(True)+'<div class="diagram-controls">'+''.join(f'<button data-court-step="{i}" aria-pressed="{str(i==0).lower()}">{t}</button>' for i,t in enumerate(['① 线路被挡','② 拉开角度','③ 传后切入']))+'</div><p data-court-caption aria-live="polite"></p></div>'
def shell(title,b,path,lesson=''):
 base='../'*(len(Path(path).parts)-1)
 nav=''.join(f'<a href="{base}{u}">{t}</a>' for u,t in [('catalog.html','全部课程'),('path.html','从零开始'),('court.html','球场实验室'),('notebook.html','我的学习')])
 s=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="第一球：面向零基础的中文篮球入门手册，独立短课、规则自测、跑位图解与练习笔记。"><meta name="theme-color" content="#302a23"><title>{E(title)} · 第一球</title><link rel="icon" href="{base}assets/favicon.svg"><link rel="stylesheet" href="{base}assets/style.css"><script defer src="{base}assets/course-data.js"></script><script defer src="{base}assets/app.js"></script></head><body data-base="{base}" data-lesson="{lesson}"><a class="skip" href="#main">跳到正文</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="{base}index.html"><span class="brand-mark">1</span><span><b>第一球</b><small>THE FIRST SHOT · BASKETBALL GUIDE</small></span></a><nav aria-label="主导航">{nav}</nav></div></header><main class="wrap" id="main">{b}</main><footer class="wrap footer"><div><strong>第一球 · 从零开始打篮球</strong><br>把动作拆小，把第一球投出去。<br>独立中文学习资料站 · 非 FIBA 官方网站</div><div class="footer-links"><a href="{base}sources.html">来源与编辑说明</a><a href="https://github.com/yanzh23324-star/basketball-from-zero">GitHub ↗</a><span>进度与笔记仅保存在当前浏览器</span></div></footer></body></html>'''
 f=O/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(s)
def card(c,base=''):
 return f'<a class="lesson-card" href="{base}learn/{c["id"]}.html" data-course="{c["id"]}" data-category="{c["category"]}" data-search="{E(c["title"]+c["lead"])}"><span class="lesson-index">{L.index(c)+1:02}</span><div><span class="card-label">{M[c["category"]][1]}</span><h3>{E(c["title"])}</h3><p>{E(c["lead"])}</p><small>约 3 分钟 · 含练习与自测 <span data-read-badge></span></small></div></a>'
def head(en,title):return f'<div class="section-head"><div><div class="eyebrow">{en}</div><h2>{title}</h2></div></div>'
def build():
 O.mkdir(exist_ok=True);(O/'assets').mkdir(exist_ok=True)
 for n in ['style.css','app.js','favicon.svg']:shutil.copyfile(R/'assets'/n,O/'assets'/n)
 (O/'assets/course-data.js').write_text('window.BASKETBALL_COURSES='+json.dumps([dict(id=c['id'],title=c['title'],category=c['category'],categoryName=M[c['category']][1]) for c in L],ensure_ascii=False)+';')
 b='''<section class="hero"><div><div class="eyebrow">A BEGINNER’S COURT GUIDE / 零基础上场手册</div><h1>不必先厉害，<br>先投出<em>第一球。</em></h1><p>不会运球、总投不进、不知道往哪跑？<br>把篮球拆成一个个看得懂、能试试的小问题。<br>从第一次拿球，到完成第一次配合。</p><div class="hero-actions"><a class="btn" href="path.html">跟着路线，从零开始 ↗</a><a class="btn secondary" href="catalog.html">找一个具体问题</a></div><div class="small-rule"><span>● 中文图文短课</span><span>● 无需注册</span><span>● 按自己的节奏</span></div></div><div class="hero-board"><div class="sticker">先懂一点<br>就去试试</div><div class="board-top"><span>COURT NOTES / 01</span><span>THERE IS ROOM FOR YOU</span></div><h3>第一课：给队友一条传球路线。</h3>'''+court()+'''<div class="board-note">球不在你手里，观察与移动也能帮助球队。<br><a href="court.html">打开接应实验室，换个角度看看 ↗</a></div></div></section>'''
 b+=f'<div class="intro-strip"><span><strong>05</strong> 个学习板块</span><span><strong>{len(L):02}</strong> 节独立短课</span><span><strong>01</strong> 次练一个小目标</span></div><section class="section">'+head('CHOOSE YOUR CHAPTER','你想先弄明白什么？')+'<div class="topic-grid">'
 for i,(cid,t,short,desc) in enumerate(CATS):b+=f'<a class="topic-card" href="topics/{cid}.html"><span class="topic-num">0{i+1}</span><span class="topic-arrow">↗</span><h3>{t}</h3><p>{desc}</p><div class="topic-bottom"><span>{sum(c["category"]==cid for c in L)} 节短课</span><span>进入板块 →</span></div></a>'
 b+='''<a class="topic-card lab-card" href="court.html"><span class="topic-num">↗</span><h3>球场实验室</h3><p>为什么没人传给我？点击三步图解，看传球角度如何改变。</p><div class="topic-bottom">可交互图解 · 打开实验室 →</div></a></div></section><section class="route-band"><div><div class="eyebrow">YOUR FIRST FOUR WEEKS</div><h2>每次只练一件事，<br>慢慢找到球感。</h2><p>认识比赛 → 控住球 → 传投结合 → 小场配合。<br>周数是参考，稳定了再进入下一阶段。</p><a class="text-link" href="path.html">打开完整学习路线 ↗</a></div><div class="route-mini"><a href="learn/dribble.html"><span>01</span>让球听话<br>从原地运球开始</a><a href="learn/pass.html"><span>02</span>把球传到<br>队友好接的位置</a><a href="learn/space.html"><span>03</span>传完球后<br>再给一个选择</a></div></section>'''
 shell('从零开始打篮球',b,'index.html')
 for cid,t,short,desc in CATS:
  shell(t,f'<div class="crumb"><a href="../index.html">首页</a> / {t}</div><section class="category-cover"><div><div class="eyebrow">CHAPTER / {cid.upper()}</div><h1>{t}</h1><p>{short}。<br>{desc}</p></div><div class="category-graphic">{court()}</div></section><div class="lesson-list">'+''.join(card(c,'../') for c in L if c['category']==cid)+'</div>','topics/'+cid+'.html')
 for i,c in enumerate(L):
  q=c['quiz'];b=f'<div class="crumb"><a href="../index.html">首页</a> / <a href="../topics/{c["category"]}.html">{M[c["category"]][1]}</a> / 本课</div><div class="article-layout"><aside class="article-side"><div class="sticky-toc"><p class="eyebrow">LESSON {i+1:02} / {len(L)}</p><nav class="toc" aria-label="本课目录">'+''.join(f'<a href="#s{j}">{s["title"]}</a>' for j,s in enumerate(c['sections']))+'<a href="#practice">试一试</a><a href="#quiz">一道自测</a></nav></div></aside><article class="lesson-article"><div class="eyebrow">'+M[c['category']][1]+f'</div><h1>{E(c["title"])}</h1><p class="article-lead">{E(c["lead"])}</p><div class="lesson-toolbar"><button data-read-button="{c["id"]}" aria-pressed="false">标记为已读</button><button data-save-button="{c["id"]}" aria-pressed="false">☆ 收藏这课</button></div>'
  b+=''.join(f'<section id="s{j}"><h2>{s["title"]}</h2><p>{s["text"]}</p></section>' for j,s in enumerate(c['sections']))
